# Generated by build.py from recipe.yml for recipe surl-find-the-port-it-chose. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'find-port.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Starts surl on a free port, waits for its Listening on line, reads the port from it,`n# fetches hello.txt with curl, and stops surl. Arguments, if given, replace surl's.`n[ `$# -gt 0 ] || set -- --directory site http://127.0.0.1:0/`nsurl `"`$@`" > listening.txt 2> surl.log &`npid=`$!`ndeadline=`$(( `$(date +%s) + 5 ))   # wait at most about 5 seconds, however slow the machine`nuntil grep -q '^Listening on ' listening.txt; do`n  if ! kill -0 `"`$pid`" 2>/dev/null; then   # surl gave up: show why and pass on its code`n    wait `"`$pid`"; code=`$?; cat surl.log >&2; exit `$code`n  fi`n  if [ `"`$(date +%s)`" -ge `"`$deadline`" ]; then echo `"no Listening on line from surl`" >&2; kill `"`$pid`"; exit 1; fi`n  sleep 0.1`ndone`nurl=`$(sed -n 's|^Listening on ||p' listening.txt | head -n 1)`nport=`${url##*:}; port=`${port%/}`necho `"port `$port`"`ncurl -s `"`${url}hello.txt`"`nstatus=`$?`nkill `"`$pid`"`nexit `$status`n")
sh find-port.sh
